/**
 * Notification severity levels.
 *
 * - `Debug`: Debugging info.
 * - `Info`: General info.
 * - `AlertLow`: Low-priority alerts.
 * - `AlertGuarded`: Guarded alerts.
 * - `AlertElevated`: Elevated alerts.
 * - `AlertHigh`: High alerts.
 * - `AlertSevere`: Severe alerts.
 */
export const Debug = 0;
export const Info = 1;
export const AlertLow = 2;
export const AlertGuarded = 3;
export const AlertElevated = 4;
export const AlertHigh = 5;
export const AlertSevere = 6;
